# Generated by Phase: IMPLEMENT | Feature: EVOL-048
"""One planning stage — never zero, never two (EVOL-048).

Every change to a governed path is covered by exactly one approved plan.
  governed   `planning.governed_paths` (globs) minus `planning.docs_exempt` — except `planning.gate_inputs`, documents a
             gate reads, governed like code whatever their extension.
  classes    `planning.exempt_classes` — the branch classes whose plan a framework phase owns (a feature's CODESIGN /
             BLUEPRINT / IMPLEMENT --plan artefacts). Every unlisted class is gated — fail closed.
  approval   a marker written only by the harness's plan approval (`gate.py plan --record` fed the PostToolUse
             ExitPlanMode payload), or the branch's own plan artefact (`planning.plan_artefact`, `{ID}` = the feature
             id of the branch) in an approved state. A marker approved on another branch (the plan came before the
             branch was cut) is adopted ONCE by the first gated branch that asks, within `adoption_window_minutes`.
  never two  a command that owns a planning phase never enters plan mode — stated in the command files, not here.
"""
from __future__ import annotations

import datetime as dt
import json
import re
from pathlib import Path

from . import branch as branch_mod
from .common import GateFault, any_glob, key, read_frontmatter

APPROVED_STATES = {"APPROVED", "ACCEPTED", "BUILDING", "IMPLEMENTED_AND_VERIFIED", "READY"}
STATE_DIR = ".claude/state"


def _cfg(repo: Path) -> dict:
    p = key(repo, "planning", default=None)
    if not isinstance(p, dict):
        raise GateFault("config key `planning` is missing from config/quality.json — governed paths, exempt classes and the plan artefact live there (SETUP materialises it)")
    out = {}
    for k in ("governed_paths", "docs_exempt", "gate_inputs", "exempt_classes"):
        v = p.get(k, [])
        if not isinstance(v, list):
            raise GateFault(f"planning.{k} must be a list")
        out[k] = [str(x) for x in v]
    out["plan_artefact"] = p.get("plan_artefact") or None
    try:
        out["window"] = int(p.get("adoption_window_minutes", 30))
    except (TypeError, ValueError):
        raise GateFault("planning.adoption_window_minutes must be an integer (minutes)") from None
    return out


def governed(repo: Path, path: str, cfg: dict | None = None) -> tuple[bool, str]:
    cfg = cfg or _cfg(repo)
    rel = path
    try:
        rel = str(Path(path).resolve().relative_to(repo))
    except ValueError:
        pass
    if any_glob(rel, cfg["gate_inputs"]):
        return True, "an input of a gate — governed like code whatever its extension"
    if any_glob(rel, cfg["docs_exempt"]):
        return False, "a documentation target — no plan owed"
    if any_glob(rel, cfg["governed_paths"]):
        return True, "a governed path"
    return False, "outside the governed paths"


def _slug(branch: str) -> str:
    return re.sub(r"[^A-Za-z0-9._-]+", "-", branch)


def marker_path(repo: Path, branch: str) -> Path:
    return repo / STATE_DIR / f"plan-approved-{_slug(branch)}.json"


def _read_marker(p: Path) -> dict | None:
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) and d.get("approved_at") else None
    except (OSError, ValueError):
        return None


def _now() -> dt.datetime:
    return dt.datetime.now(dt.timezone.utc)


def _age_minutes(marker: dict) -> float | None:
    try:
        t = dt.datetime.fromisoformat(str(marker["approved_at"]).replace("Z", "+00:00"))
        return (_now() - t).total_seconds() / 60
    except (KeyError, ValueError):
        return None


def record(repo: Path, payload: dict, branch: str | None = None) -> dict:
    """Write the approval marker from the harness's PostToolUse ExitPlanMode payload — and from nothing else."""
    if not isinstance(payload, dict) or payload.get("hook_event_name") != "PostToolUse" or payload.get("tool_name") != "ExitPlanMode":
        raise GateFault("a plan approval is recorded only from the harness's PostToolUse ExitPlanMode event — this payload is not one; nothing written")
    b = branch or branch_mod.current_branch(repo)
    m = {"branch": b, "approved_at": _now().isoformat(timespec="seconds").replace("+00:00", "Z"), "session_id": str(payload.get("session_id") or ""),
         "source": "harness:ExitPlanMode", "adopted_by": None}
    p = marker_path(repo, b)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(m, indent=1) + "\n", encoding="utf-8")
    return m


def _artefact(repo: Path, cfg: dict, branch: str) -> tuple[bool, str]:
    tmpl = cfg["plan_artefact"]
    if not tmpl:
        return False, ""
    fid = branch_mod.branch_class(repo, branch).get("feature_id")
    if not fid:
        m = re.search(r"/([A-Z][A-Z0-9]*-[0-9A-Z]+(?:-[0-9A-Z]+)*)", branch)
        fid = m.group(1) if m else None
    if not fid:
        return False, f"no feature id in `{branch}` — the plan artefact {tmpl} cannot be located"
    rel = tmpl.replace("{ID}", fid)
    p = repo / rel
    if not p.is_file():
        return False, f"the plan artefact {rel} does not exist"
    try:
        st = str(read_frontmatter(p).get("status", "")).upper()
    except GateFault as e:
        return False, f"{rel} has an unreadable frontmatter ({e})"
    if st in APPROVED_STATES:
        return True, f"the plan artefact {rel} is {st}"
    return False, f"the plan artefact {rel} is `{st or 'without status'}`, not an approved state"


def approval(repo: Path, branch: str | None = None, cfg: dict | None = None, adopt: bool = True) -> dict:
    """{approved, source, reason, class, branch}. Fail closed: an unlisted class without approval is not approved.
    adopt=False (the advisory) reports an adoptable approval without consuming it — adoption happens on a real write."""
    cfg = cfg or _cfg(repo)
    b = branch or branch_mod.current_branch(repo)
    info = branch_mod.branch_class(repo, b)
    cls = info["class"]
    if cls in cfg["exempt_classes"]:
        return {"approved": True, "source": "phase", "reason": f"class `{cls}` — a framework phase owns its plan", "class": cls, "branch": b}
    ok, why = _artefact(repo, cfg, b)
    if ok:
        return {"approved": True, "source": "artefact", "reason": why, "class": cls, "branch": b}
    own = _read_marker(marker_path(repo, b))
    if own:
        return {"approved": True, "source": own.get("source", "marker"), "reason": f"plan approved on this branch at {own['approved_at']}", "class": cls, "branch": b}
    # adoption: a plan approved on the base branch just before this one was cut — once, within the window
    state = repo / STATE_DIR
    candidates = []
    if state.is_dir():
        for p in sorted(state.glob("plan-approved-*.json")):
            m = _read_marker(p)
            if m and m.get("branch") != b and not m.get("adopted_by") and branch_mod.branch_class(repo, str(m["branch"]))["class"] == "protected":
                candidates.append((p, m))
    expired = []
    for p, m in candidates:
        age = _age_minutes(m)
        if age is not None and age <= cfg["window"]:
            if not adopt:
                return {"approved": True, "source": "adoptable", "reason": f"plan approved on `{m['branch']}` at {m['approved_at']} will be adopted by the first governed write of this branch", "class": cls, "branch": b}
            m["adopted_by"] = b; m["adopted_at"] = _now().isoformat(timespec="seconds").replace("+00:00", "Z")
            p.write_text(json.dumps(m, indent=1) + "\n", encoding="utf-8")
            marker_path(repo, b).write_text(json.dumps({**m, "branch": b, "source": f"adopted from {m['branch']}"}, indent=1) + "\n", encoding="utf-8")
            return {"approved": True, "source": "adopted", "reason": f"plan approved on `{m['branch']}` at {m['approved_at']} adopted by this branch (single use)", "class": cls, "branch": b}
        expired.append(f"{m['branch']} ({int(age) if age is not None else '?'} min ago)")
    tail = f"; an approval on {', '.join(expired)} is outside the {cfg['window']}-minute adoption window" if expired else ""
    return {"approved": False, "source": None, "class": cls, "branch": b,
            "reason": (f"branch `{b}` (class `{cls}`) has no framework planning phase and no approved plan" + (f" — {why}" if why else "") + tail)}


def gate(repo: Path, path: str, branch: str | None = None) -> dict:
    """{block, governed, reason, resolution}."""
    cfg = _cfg(repo)
    g, why = governed(repo, path, cfg)
    if not g:
        return {"block": False, "governed": False, "reason": why, "resolution": ""}
    a = approval(repo, branch, cfg)
    if a["approved"]:
        return {"block": False, "governed": True, "reason": f"{why}; {a['reason']}", "resolution": ""}
    res = ("Resolution: plan the change first — enter plan mode and have the user approve it (the approval writes the marker), "
           + (f"or bring {cfg['plan_artefact'].replace('{ID}', '{ID}')} to an approved state; " if cfg["plan_artefact"] else "")
           + "documentation targets need no plan.")
    return {"block": True, "governed": True, "reason": f"{why}; {a['reason']}", "resolution": res}


def status(repo: Path, branch: str | None = None) -> dict:
    cfg = _cfg(repo)
    try:
        a = approval(repo, branch, cfg, adopt=False)
    except GateFault as e:
        return {"warn": False, "line": f"planning: could not classify ({e})"}
    if a["approved"]:
        return {"warn": False, "line": f"planning: {a['branch']} — {a['reason']}"}
    return {"warn": True, "line": f"planning: {a['reason']}. A write to a governed path will be BLOCKED until a plan is approved (plan mode → user approval) — documentation targets stay open."}
